<script setup lang="ts">const props=defineProps<{html:string}>();const root=ref<HTMLElement>();async function renderBlocks(){if(!root.value)return;const katex=await import('katex');for(const el of root.value.querySelectorAll<HTMLElement>('.math-inline,.math-block')){const source=el.dataset.latex||el.textContent||'';try{katex.default.render(source,el,{displayMode:el.classList.contains('math-block'),throwOnError:false,trust:false})}catch{el.textContent=source}}const blocks=[...root.value.querySelectorAll<HTMLElement>('.mermaid')];if(blocks.length){const mermaid=await import('mermaid');mermaid.default.initialize({startOnLoad:false,securityLevel:'strict',theme:'neutral'});for(const [index,el] of blocks.entries()){try{const {svg}=await mermaid.default.render(`northstar-diagram-${index}`,el.textContent||'');el.innerHTML=svg}catch{el.textContent='无法渲染此 Mermaid 图表'}}}}onMounted(renderBlocks);watch(()=>props.html,async()=>{await nextTick();await renderBlocks()})</script><template><div ref="root" class="prose max-w-none" v-html="html"/></template>
